// Bundled settings webview entry (esbuild -> media/dist/settings.js).
// Mirrors the IntelliJ AgentExtenderConfigurable: a single merged agent table (promoted + custom
// tools) with columns Icon / ID / Display Name / Command / Base Args / Skip flag / Resume flag / Icon
// file, plus Add / Remove / Icon actions. Settings are always saved at the User (Global) scope.
// Promoted (built-in) rows are read-only and not removable, matching IDEA's locked-agent behaviour.
// Duplicate IDs/commands are blocked at Save (mirroring IDEA's apply()), and a not-runnable command or
// an unresolvable icon is reported back via the saveResult message.

declare const acquireVsCodeApi: () => {
  postMessage(msg: unknown): void;
  getState(): unknown;
  setState(state: unknown): void;
};
const vscode = acquireVsCodeApi();

interface AgentRow {
  id: string;
  displayName: string;
  command: string;
  baseArgs: string;
  iconFile: string;
  skipFlag: string;
  resumeFlag: string;
  locked: boolean;
  installed: boolean;
  iconUri?: string;
}
interface SettingsState {
  agents: AgentRow[];
}

let state: SettingsState = {
  agents: [],
};
// Currently selected row id (for Remove). Tracked separately so clicking a row doesn't force a
// re-render that would drop unsaved input focus.
let selectedId: string | null = null;

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}
function escapeAttr(s: string): string {
  return escapeHtml(s).replace(/"/g, "&quot;");
}

function slug(s: string): string {
  return s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "tool";
}

/** Filename part of a command (IDEA compares commands by baseName so /usr/local/bin/claude and
 *  claude.cmd count as the same agent). */
function baseName(cmd: string): string {
  return cmd.replace(/^.*[\\/]/, "");
}

/** Read the editable id/command of every row straight from the DOM (avoids a re-render that would
 *  drop input focus). */
function collectRows(): { id: string; command: string }[] {
  return Array.from(document.querySelectorAll<HTMLDivElement>(".arow")).map((row) => ({
    id: row.querySelector<HTMLInputElement>("input[data-f='id']")?.value.trim() ?? "",
    command: row.querySelector<HTMLInputElement>("input[data-f='command']")?.value.trim() ?? "",
  }));
}

/** Mirror IntelliJ's findDuplicates: duplicate ID (case-insensitive) or duplicate command (by baseName,
 *  case-insensitive). Empty values are ignored so a blank new row doesn't flag immediately. */
function findDuplicates(): string[] {
  const ids = new Map<string, number>();
  const cmds = new Map<string, number>();
  const dupIds = new Set<string>();
  const dupCmds = new Set<string>();
  for (const r of collectRows()) {
    const id = r.id.toLowerCase();
    const cmd = baseName(r.command).toLowerCase();
    if (id) {
      if (ids.has(id)) {
        dupIds.add(id);
      }
      ids.set(id, (ids.get(id) ?? 0) + 1);
    }
    if (cmd) {
      if (cmds.has(cmd)) {
        dupCmds.add(cmd);
      }
      cmds.set(cmd, (cmds.get(cmd) ?? 0) + 1);
    }
  }
  const problems: string[] = [];
  if (dupIds.size > 0) {
    problems.push("Duplicate ID: " + Array.from(dupIds).join(", "));
  }
  if (dupCmds.size > 0) {
    problems.push("Duplicate command: " + Array.from(dupCmds).join(", "));
  }
  return problems;
}

function reportDuplicates(): void {
  const problems = findDuplicates();
  if (problems.length > 0) {
    setStatus(problems.join("; "), true);
  } else if (document.getElementById("status")?.className === "warn") {
    setStatus("", false);
  }
}

function iconMarkup(a: AgentRow): string {
  const cls = a.installed ? "ai" : "ai missing";
  return a.iconUri
    ? `<img class="${cls}" src="${escapeAttr(a.iconUri)}" alt="" draggable="false" />`
    : `<span class="${cls}">⚡</span>`;
}

function render(): void {
  const root = document.getElementById("root")!;
  const selLocked = state.agents.find((a) => a.id === selectedId)?.locked ?? false;
  const rows = state.agents
    .map((a) => {
      const icon = iconMarkup(a);
      const dis = a.locked ? "disabled" : "";
      return `<div class="arow${a.id === selectedId ? " sel" : ""}${a.locked ? " locked" : ""}" data-id="${escapeAttr(a.id)}">
        <div class="aiwrap">${icon}</div>
        <input data-f="id" value="${escapeAttr(a.id)}" ${dis} />
        <input data-f="displayName" value="${escapeAttr(a.displayName)}" ${dis} />
        <input data-f="command" value="${escapeAttr(a.command)}" ${dis} />
        <input data-f="baseArgs" value="${escapeAttr(a.baseArgs)}" />
        <input data-f="skipFlag" value="${escapeAttr(a.skipFlag)}" />
        <input data-f="resumeFlag" value="${escapeAttr(a.resumeFlag)}" />
        <input data-f="iconFile" value="${escapeAttr(a.iconFile)}" ${dis} />
      </div>`;
    })
    .join("");

  root.innerHTML = `
    <div class="head">
      <span>Icon</span><span>ID</span><span>Display name</span><span>Command</span>
      <span>Base args</span><span>Skip flag</span><span>Resume flag</span><span>Icon file</span>
    </div>
    <div class="arows">${rows}</div>
    <div class="actions">
      <button id="addTool">+ Add</button>
      <button id="removeTool">− Remove</button>
      <button id="pickIconBtn" type="button" title="Choose icon for the selected agent"${
    selLocked ? " disabled" : ""
  }>Icon…</button>
      <span id="status"></span>
      <button id="save" class="primary">Save</button>
    </div>`;

  document.getElementById("save")!.addEventListener("click", save);
  document.getElementById("addTool")!.addEventListener("click", addTool);
  document.getElementById("removeTool")!.addEventListener("click", removeTool);
  document.getElementById("pickIconBtn")!.addEventListener("click", pickSelectedIcon);
  updateIconBtnState();

  // Row selection: toggle highlight without re-rendering (preserves input focus).
  root.querySelectorAll<HTMLDivElement>(".arow").forEach((row) => {
    row.addEventListener("click", (e) => {
      const tag = (e.target as HTMLElement).tagName;
      if (tag === "INPUT" || tag === "BUTTON") {
        return; // let inputs/buttons keep focus; selection still updates on other clicks
      }
      selectedId = row.dataset.id ?? null;
      root.querySelectorAll(".arow").forEach((r) => r.classList.remove("sel"));
      row.classList.add("sel");
      // Built-in (locked) agents can't change their icon — disable the Icon button for them.
      updateIconBtnState();
    });
  });

  // Live duplicate detection (ID / command) as the user types — mirrors IDEA's reportDuplicates.
  root.querySelector<HTMLDivElement>(".arows")?.addEventListener("input", reportDuplicates);
  reportDuplicates();
}

/** Read the current DOM rows back into state.agents so Add/Remove don't lose unsaved edits. */
function syncFromDom(): void {
  const byId = new Map(state.agents.map((a) => [a.id, a]));
  document.querySelectorAll<HTMLDivElement>(".arow").forEach((row) => {
    const id = row.dataset.id ?? "";
    const a = byId.get(id);
    if (!a) {
      return;
    }
    const get = (f: string) =>
      row.querySelector<HTMLInputElement>(`input[data-f='${f}']`)?.value ?? "";
    if (!a.locked) {
      a.id = get("id").trim();
    }
    a.displayName = get("displayName").trim();
    a.command = get("command").trim();
    a.baseArgs = get("baseArgs").trim();
    a.skipFlag = get("skipFlag").trim();
    a.resumeFlag = get("resumeFlag").trim();
    a.iconFile = get("iconFile").trim();
  });
}

function addTool(): void {
  syncFromDom();
  const id = `custom.${slug("tool" + (state.agents.length + 1))}`;
  state.agents.push({
    id,
    displayName: "",
    command: "",
    baseArgs: "",
    iconFile: "",
    skipFlag: "",
    resumeFlag: "",
    locked: false,
    installed: false,
  });
  selectedId = id;
  render();
}

function removeTool(): void {
  syncFromDom(); // preserve edits made in other rows before re-rendering
  if (!selectedId) {
    setStatus("Select a row first", true);
    return;
  }
  const target = state.agents.find((a) => a.id === selectedId);
  if (target?.locked) {
    setStatus(`Cannot remove built-in agent "${target.id}"`, true);
    return;
  }
  state.agents = state.agents.filter((a) => a.id !== selectedId);
  selectedId = null;
  render();
}

/** Enable/disable the Icon button based on whether the selected row is a built-in (locked) agent. */
function updateIconBtnState(): void {
  const btn = document.getElementById("pickIconBtn") as HTMLButtonElement | null;
  if (!btn) {
    return;
  }
  const a = state.agents.find((x) => x.id === selectedId);
  btn.disabled = Boolean(a?.locked);
}

/** Open the native icon file chooser for the currently selected row. */
function pickSelectedIcon(): void {
  if (!selectedId) {
    setStatus("Select a row first", true);
    return;
  }
  const a = state.agents.find((x) => x.id === selectedId);
  if (a?.locked) {
    setStatus(`Built-in agent "${a.id}" can't change its icon`, true);
    return;
  }
  vscode.postMessage({ type: "pickIcon", rowId: selectedId });
}

function setStatus(text: string, warn: boolean): void {
  const el = document.getElementById("status");
  if (el) {
    el.textContent = text;
    el.className = warn ? "warn" : "";
  }
}

function save(): void {
  syncFromDom(); // capture in-progress edits from the inputs before building the payload
  // Block saving on duplicate ID/command, like IDEA's apply() throwing ConfigurationException.
  const problems = findDuplicates();
  if (problems.length > 0) {
    setStatus(problems.join("; "), true);
    return;
  }
  const agents = state.agents.map((a) => ({
    id: a.id,
    displayName: a.displayName,
    command: a.command,
    baseArgs: a.baseArgs,
    iconFile: a.iconFile,
    skipFlag: a.skipFlag,
    resumeFlag: a.resumeFlag,
    locked: a.locked,
    installed: a.installed,
    iconUri: a.iconUri,
  }));
  vscode.postMessage({ type: "save", agents });
  setStatus("Saving…", false);
}

/** Update each row's install state from a set of installed commands (lower-cased). Greys out the icon
 *  of uninstalled agents (toggling the `.missing` class on the icon element only) — never rebuilds the
 *  table, so in-progress edits are preserved. Mirrors IDEA's setInstalled(). Rows are matched by their
 *  `data-id` attribute (not a CSS selector built from the id) so it stays correct even after the user
 *  edits the ID field in place. */
function applyInstalled(installedCmds: string[]): void {
  const set = new Set(installedCmds.map((c) => c.toLowerCase()));
  document.querySelectorAll<HTMLDivElement>(".arow").forEach((row) => {
    const id = row.dataset.id ?? "";
    const a = state.agents.find((x) => x.id === id);
    if (!a) {
      return;
    }
    const ok = a.command.trim().length > 0 && set.has(a.command.toLowerCase());
    a.installed = ok;
    row.querySelector<HTMLElement>(".ai")?.classList.toggle("missing", !ok);
  });
}

window.addEventListener("message", (ev: MessageEvent) => {
  const msg = ev.data;
  if (msg.type === "config") {
    state = msg.state;
    // Preserve the current selection across re-renders (e.g. after Save the host re-sends the config
    // to reflect persisted icon/iconUri) instead of snapping back to the first row.
    if (!selectedId || !state.agents.some((a) => a.id === selectedId)) {
      selectedId = state.agents.find((a) => !a.locked)?.id ?? state.agents[0]?.id ?? null;
    }
    render();
  } else if (msg.type === "installed") {
    // Background cache refresh from the host: re-grey the icons without rebuilding the table.
    applyInstalled(msg.installed ?? []);
  } else if (msg.type === "saveResult") {
    // Host finished the save: show success, or surface a blocked save (e.g. a not-runnable agent).
    // Non-blocking warnings (dropped empty rows, unresolvable icons) are shown alongside the success.
    if (msg.ok) {
      const warns: string[] = Array.isArray(msg.warnings) ? msg.warnings : [];
      if (warns.length > 0) {
        setStatus("Saved ✓ — " + warns.join("; "), true);
      } else {
        setStatus("Saved ✓", false);
        setTimeout(() => setStatus("", false), 1500);
      }
    } else {
      setStatus(msg.message ?? "Save failed", true);
    }
  } else if (msg.type === "iconChosen") {
    // Host resolved a picked image file: write it into the row's input + refresh its preview icon.
    const a = state.agents.find((x) => x.id === msg.rowId);
    if (!a) {
      return;
    }
    a.iconFile = msg.value;
    a.iconUri = msg.iconUri;
    const row = Array.from(document.querySelectorAll<HTMLDivElement>(".arow")).find(
      (r) => r.dataset.id === msg.rowId
    );
    if (row) {
      const input = row.querySelector<HTMLInputElement>("input[data-f='iconFile']");
      if (input) {
        input.value = msg.value;
      }
      row.querySelector<HTMLElement>(".aiwrap")!.innerHTML = iconMarkup(a);
    }
  }
});

vscode.postMessage({ type: "ready" });
